BLACK = "B"
WHITE = "W"
NONE = ""


class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self._rows = board

    def _neighbors(self, x, y):
        """Yield in-bounds horizontal/vertical neighbours of (x, y)."""
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= ny < len(self._rows) and 0 <= nx < len(self._rows[ny]):
                yield (nx, ny)

    def _flood(self, x, y):
        """Flood fill the empty region reachable from (x, y).

        The starting cell is included even if it is a stone, so that a
        stone coordinate can be used to inspect the surrounding region.

        Returns:
            (set, set): the region of coordinates, and the set of stone
            colours adjacent to that region.
        """
        rows = self._rows
        region = set()
        queue = [(x, y)]
        while queue:
            cx, cy = queue.pop()
            if (cx, cy) in region:
                continue
            if (cx, cy) != (x, y) and rows[cy][cx] != " ":
                continue
            region.add((cx, cy))
            for nx, ny in self._neighbors(cx, cy):
                if (nx, ny) not in region:
                    queue.append((nx, ny))
        owners = set()
        for cx, cy in region:
            for nx, ny in self._neighbors(cx, cy):
                stone = rows[ny][nx]
                if stone != " " and (nx, ny) not in region:
                    owners.add(stone)
        return region, owners

    def territory(self, x, y):
        """Find the owner and the territories given a coordinate on
           the board

        Args:
            x (int): Column on the board
            y (int): Row on the board

        Returns:
            (str, set): A tuple, the first element being the owner
                        of that area.  One of "W", "B", "".  The
                        second being a set of coordinates, representing
                        the owner's territories.
        """
        rows = self._rows
        if not (0 <= y < len(rows) and 0 <= x < len(rows[y])):
            raise ValueError("Invalid coordinate")
        cell = rows[y][x]
        region, owners = self._flood(x, y)
        if cell == " ":
            if len(owners) == 1:
                return owners.pop(), region
            return NONE, region
        if owners == {cell}:
            return cell, {(x, y)}
        return NONE, set()

    def territories(self):
        """Find the owners and the territories of the whole board

        Args:
            none

        Returns:
            dict(str, set): A dictionary whose key being the owner
                        , i.e. "W", "B", "".  The value being a set
                        of coordinates owned by the owner.
        """
        result = {BLACK: set(), WHITE: set(), NONE: set()}
        visited = set()
        for y, row in enumerate(self._rows):
            for x, _ in enumerate(row):
                if (x, y) in visited:
                    continue
                if row[x] != " ":
                    continue
                region, owners = self._flood(x, y)
                visited |= region
                if len(owners) == 1:
                    owner = owners.pop()
                else:
                    owner = NONE
                result[owner] |= region
        return result
